# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                // Maximum connections in pool
  min: 2,                 // Minimum connections to maintain

  // Timeout settings (milliseconds)
  connectionTimeoutMillis: 5000,   // Wait for available connection
  idleTimeoutMillis: 30000,        // Close idle connections after
  query_timeout: 10000,            // Cancel queries running longer than this
  statement_timeout: 10000,        // Server-side query timeout

  // SSL (production)
  ssl: process.env.NODE_ENV === 'production' 
    ? { rejectUnauthorized: true } 
    : false,
});

// Handle unexpected errors on idle clients
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err);
  process.exit(-1); // Or handle more gracefully
});

pool.on('connect', (client) => {
  console.log('New client connected to pool');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

module.exports = pool;
```

## Query Wrapper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Execute a simple query using a pool connection
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    if (duration > 1000) {
      console.warn('Slow query detected:', { text, duration, rows: result.rowCount });
    }

    return result;
  } catch (err) {
    console.error('Query error:', { text, params, error: err.message });
    throw err; // Re-throw for caller to handle
  }
}

/**
 * Execute queries within a transaction
 */
async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Always release back to pool
  }
}

/**
 * Execute multiple queries with a dedicated client
 */
async function withClient(callback) {
  const client = await pool.connect();

  try {
    return await callback(client);
  } finally {
    client.release();
  }
}

module.exports = { query, withTransaction, withClient };
```

## Usage Examples

```javascript
// services/userService.js
const { query, withTransaction, withClient } = require('../db/query');

// Simple query
async function getUserById(id) {
  const { rows } = await query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [id]
  );
  return rows[0] || null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    // Both queries use the SAME client = same transaction
    const { rows } = await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2 RETURNING balance',
      [amount, fromId]
    );

    if (rows[0].balance < 0) {
      throw new Error('Insufficient funds'); // Triggers ROLLBACK
    }

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query(
      'INSERT INTO transactions (from_id, to_id, amount) VALUES ($1, $2, $3)',
      [fromId, toId, amount]
    );

    return { success: true, newBalance: rows[0].balance };
  });
}

// Multiple related queries with one client
async function getUserWithPosts(userId) {
  return withClient(async (client) => {
    const { rows: [user] } = await client.query(
      'SELECT * FROM users WHERE id = $1', [userId]
    );

    const { rows: posts } = await client.query(
      'SELECT * FROM posts WHERE user_id = $1 ORDER BY created_at DESC',
      [userId]
    );

    return { ...user, posts };
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`Received ${signal}, shutting down gracefully...`);

  try {
    await pool.end(); // Drain pool before exiting
    console.log('Pool has ended');
    process.exit(0);
  } catch (err) {
    console.error('Error during shutdown:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Pool Health Check

```javascript
// db/healthCheck.js
const pool = require('./pool');

async function checkDatabaseHealth() {
  const client = await pool.connect();

  try {
    const start = Date.now();
    await client.query('SELECT 1');

    return {
      status: 'healthy',
      latency: Date.now() - start,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  } catch (err) {
    return { status: 'unhealthy', error: err.message };
  } finally {
    client.release();
  }
}

module.exports = { checkDatabaseHealth };
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---|---|---|
| `max` | 5–10 | 10–20 (tune per CPU) |
| `min` | 0–2 | 2–5 |
| `connectionTimeoutMillis` | 5000 | 3000–5000 |
| `idleTimeoutMillis` | 10000 | 30000 |
| `query_timeout` | 30000 | 5000–10000 |

## Critical Rules to Follow

1. **Always release clients** — use `try/finally` or helper wrappers
2. **Never `pool.end()` per request** — only on app shutdown
3. **Use `$1, $2` placeholders** — never string concatenate SQL (SQL injection)
4. **Set `max` below DB's `max_connections`** — leave room for admin connections
5. **Use `withTransaction`** for multi-step operations to ensure atomicity
